import json
import os


def order_total(order):
    return sum(i["qty"] * i["price_cents"] for i in order.get("items") or [])


def main():
    base = os.environ["INPUT"]
    with open(os.path.join(base, "orders.json"), encoding="utf-8") as f:
        orders = json.load(f)

    paid = {}
    ref_n = 0
    ref_total = 0
    pend = 0
    for o in orders:
        st = o.get("status")
        if st == "paid":
            c = paid.setdefault(o["customer"], [0, 0])
            c[0] += 1
            c[1] += order_total(o)
        elif st == "refunded":
            ref_n += 1
            ref_total += order_total(o)
        elif st == "pending":
            pend += 1

    for name in sorted(paid, key=lambda n: n.encode("utf-8")):
        n, t = paid[name]
        print(f"{name} {n} {t}")
    print(f"refunded {ref_n} {ref_total}")
    print(f"pending {pend}")


main()

import os
import re

def to_roman(n):
    vals = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"),
            (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"),
            (5, "V"), (4, "IV"), (1, "I")]
    out = []
    for v, s in vals:
        while n >= v:
            out.append(s)
            n -= v
    return "".join(out)

def from_roman(s):
    m = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    for i, ch in enumerate(s):
        v = m[ch]
        if i + 1 < len(s) and m[s[i + 1]] > v:
            total -= v
        else:
            total += v
    return total

