import os

def to_roman(n):
    vals = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"),
            (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"),
            (5, "V"), (4, "IV"), (1, "I")]
    out = []
    for v, s in vals:
        while n >= v:
            out.append(s)
            n -= v
    return "".join(out)

def from_roman(s):
    m = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    for i, ch in enumerate(s):
        v = m[ch]
        if i + 1 < len(s) and m[s[i + 1]] > v:
            total -= v
        else:
            total += v
    return total

def convert(v):
    if v.isascii() and v.isdigit():
        n = int(v)
        if 1 <= n <= 3999:
            return to_roman(n)
        return "invalid"
    if v and all(c in "IVXLCDM" for c in v):
        n = from_roman(v)
        if 1 <= n <= 3999 and to_roman(n) == v:
            return str(n)
    return "invalid"

