import os

def check(line):
    pairs = {')': '(', ']': '[', '}': '{'}
    closer = {'(': ')', '[': ']', '{': '}'}
    stack = []
    for i, ch in enumerate(line, 1):
        if ch in closer:
            stack.append(ch)
        elif ch in pairs:
            if not stack:
                return "col %d: unexpected %s" % (i, ch)
            top = stack[-1]
            if top != pairs[ch]:
                return "col %d: expected %s, found %s" % (i, closer[top], ch)
            stack.pop()
    if stack:
        return "unclosed " + closer[stack[-1]]
    return "ok"

def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "snippets.txt"), "r", newline="") as f:
        text = f.read()
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    out = []
    for ln in lines:
        if ln.endswith("\r"):
            ln = ln[:-1]
        out.append(check(ln))
    if out:
        print("\n".join(out))

