import os


def main():
    d = os.environ["INPUT"]
    groups = {}
    with open(os.path.join(d, "timings.log"), "rb") as f:
        data = f.read().decode("utf-8", errors="replace")
    for line in data.split("\n"):
        parts = line.split()
        if len(parts) != 3:
            continue
        m, p, t = parts
        s = t[1:] if t.startswith("-") else t
        if not (s.isascii() and s.isdigit()):
            continue
        groups.setdefault((m, p), []).append(int(t))
    for key in sorted(groups, key=lambda k: (k[0].encode("utf-8", "surrogateescape"),
                                              k[1].encode("utf-8", "surrogateescape"))):
        ts = sorted(groups[key])
        n = len(ts)

        def pct(P):
            return ts[(P * n + 99) // 100 - 1]

        print(f"{key[0]} {key[1]} count={n} p50={pct(50)} p95={pct(95)} max={ts[-1]}")


