import os, heapq

def main():
    base = os.environ.get("INPUT", "input")
    adj = {}
    trips = []
    with open(os.path.join(base, "routes.txt"), encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            p = line.split()
            if p[0] == "road" and len(p) >= 4:
                x, y, c = p[1], p[2], int(p[3])
                adj.setdefault(x, []).append((y, c))
                adj.setdefault(y, []).append((x, c))
            elif p[0] == "trip" and len(p) >= 3:
                trips.append((p[1], p[2]))

    cache = {}

    def dijkstra(src):
        if src in cache:
            return cache[src]
        dist = {src: 0}
        pq = [(0, src)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist.get(u, float("inf")):
                continue
            for v, w in adj.get(u, ()):
                nd = d + w
                if nd < dist.get(v, float("inf")):
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))
        cache[src] = dist
        return dist

    out = []
    for x, y in trips:
        if x == y:
            out.append(f"{x} 0")
            continue
        dist = dijkstra(y)
        if x not in dist:
            out.append(f"{x} {y} unreachable")
            continue
        path = [x]
        u = x
        while u != y:
            best = None
            for v, w in adj[u]:
                if v in dist and w + dist[v] == dist[u]:
                    if best is None or v < best:
                        best = v
            u = best
            path.append(u)
        out.append(" -> ".join(path) + f" {dist[x]}")
    print("\n".join(out))

