import json
import os
import sys


def merge(base, over):
    result = dict(base) if isinstance(base, dict) else {}
    for k, v in over.items():
        if v is None:
            result.pop(k, None)
        elif isinstance(v, dict):
            b = result.get(k)
            result[k] = merge(b if isinstance(b, dict) else {}, v)
        else:
            result[k] = v
    return result


def flatten(v, path, out):
    if isinstance(v, dict):
        if not v:
            out.append((path, "{}"))
        else:
            for k, x in v.items():
                flatten(x, path + "." + k if path else k, out)
    elif isinstance(v, list):
        if not v:
            out.append((path, "[]"))
        else:
            for i, x in enumerate(v):
                flatten(x, path + "." + str(i) if path else str(i), out)
    else:
        out.append((path, json.dumps(v, ensure_ascii=False)))


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "base.json"), encoding="utf-8") as f:
        base = json.load(f)
    with open(os.path.join(d, "override.json"), encoding="utf-8") as f:
        over = json.load(f)
    merged = merge(base, over)
    out = []
    flatten(merged, "", out)
    out.sort(key=lambda p: p[0].encode("utf-8"))
    sys.stdout.write("".join(p + "=" + v + "\n" for p, v in out))


main()

