import os


def main():
    inp = os.environ["INPUT"]
    out = os.environ["OUT"]
    with open(os.path.join(inp, "app.log"), encoding="utf-8", errors="surrogateescape", newline="") as f:
        data = f.read()
    buckets = {"error": [], "warn": [], "info": []}
