import os

src = os.environ["SRC"]
dst = os.environ["DST"]

def names(d):
    return sorted(n for n in os.listdir(d) if os.path.isfile(os.path.join(d, n)))

def read(p):
    with open(p, "rb") as f:
        return f.read()

src_names = names(src)
dst_names = names(dst)
src_set = set(src_names)
# byte order sort
src_names.sort(key=lambda n: os.fsencode(n))

for n in src_names:
    data = read(os.path.join(src, n))
    dp = os.path.join(dst, n)
    if not os.path.exists(dp):
        status = "added"
    elif read(dp) != data:
        status = "updated"
    else:
        status = "same"
    if status != "same":
        with open(dp, "wb") as f:
            f.write(data)
    print(f"{status} {n}")

kept = sum(1 for n in dst_names if n not in src_set)
print(f"kept {kept}")

import os
import json


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["COUNTS"]

    counts = {}
    if os.path.exists(kv_path):
        try:
            with open(kv_path, "r", encoding="utf-8") as f:
                data = f.read()
            if data.strip():
                counts = json.loads(data)
        except (OSError, ValueError):
            counts = {}

    visits_path = os.path.join(input_dir, "visits.txt")
    try:
        with open(visits_path, "rb") as f:
            raw = f.read()
    except FileNotFoundError:
        raw = b""

    text = raw.decode("utf-8", errors="surrogateescape")
    for line in text.splitlines():
        page = line.strip()
        if not page:
            continue
        counts[page] = counts.get(page, 0) + 1

    tmp = kv_path + ".tmp"
    payload = json.dumps(counts, ensure_ascii=True)
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            f.write(payload)
        os.replace(tmp, kv_path)
    except OSError:
        with open(kv_path, "w", encoding="utf-8") as f:
            f.write(payload)

    items = sorted(
        counts.items(),
        key=lambda kv: (-kv[1], kv[0].encode("utf-8", errors="surrogateescape")),
    )
    out = []
    for page, total in items:
        out.append("%s %d" % (page, total))
    if out:
        os.write(1, ("\n".join(out) + "\n").encode("utf-8", errors="surrogateescape"))


main()

