            data = {}
    except (FileNotFoundError, ValueError):
        data = {}

    def add(name, pts):
        rec = data.get(name)
        if not isinstance(rec, list):
            rec = [0, 0]
        rec[0] += pts
        rec[1] += 1
        data[name] = rec

    try:
        with open(os.path.join(inp, "games.txt"), "r", encoding="utf-8", errors="surrogateescape") as f:
            text = f.read()
    except FileNotFoundError:
        text = ""

    for line in text.split("\n"):
        parts = line.split()
        if len(parts) == 2:
            add(parts[0], 3)
            add(parts[1], 0)
        elif len(parts) == 3 and parts[2] == "draw":
            add(parts[0], 1)
            add(parts[1], 1)

    with open(board_path, "w", encoding="utf-8") as f:
        json.dump(data, f)

    def key(item):
        name, (pts, played) = item
        return (-pts, played, name.encode("utf-8", "surrogateescape"))

    top = sorted(data.items(), key=key)[:3]
    for i, (name, (pts, played)) in enumerate(top, 1):
        print(f"{i}. {name} {pts} {played}")

