import os, re, json, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

PATH = os.environ.get("COUNTS")
LOCK = threading.Lock()
DATA = {}
NAME_RE = re.compile(r"[a-z0-9-]{1,32}")

if PATH and os.path.exists(PATH):
    try:
        with open(PATH, "r", encoding="utf-8") as f:
            d = json.load(f)
        if isinstance(d, dict):
            DATA = {str(k): int(v) for k, v in d.items()}
    except Exception:
        DATA = {}


def save():
    if not PATH:
        return
    with open(PATH, "w", encoding="utf-8") as f:
        json.dump(DATA, f)
        f.flush()


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send_json(self, code, obj):
        body = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def handle_any(self):
        try:
            n = int(self.headers.get("content-length") or 0)
        except ValueError:
            n = 0
        if n > 0:
            self.rfile.read(n)
        m = self.command
        p = self.path
        if "?" in p:
            p = p.split("?", 1)[0]
        if m == "POST" and p.startswith("/hit/"):
            name = p[5:]
            if not NAME_RE.fullmatch(name):
                return self.send_json(400, {"error": "bad name"})
            with LOCK:
                DATA[name] = DATA.get(name, 0) + 1
                c = DATA[name]
                save()
            return self.send_json(200, {"name": name, "count": c})
        if m == "GET" and p.startswith("/count/"):
            name = p[7:]
            if not NAME_RE.fullmatch(name):
                return self.send_json(400, {"error": "bad name"})
            with LOCK:
                c = DATA.get(name, 0)
            return self.send_json(200, {"name": name, "count": c})
        if m == "GET" and p == "/top":
            with LOCK:
                items = sorted(DATA.items(), key=lambda kv: (-kv[1], kv[0].encode()))[:3]
            return self.send_json(200, [{"name": k, "count": v} for k, v in items])
        return self.send_json(404, {"error": "not found"})

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = handle_any


class S(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True


