import os
import json
import re
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

STORE = os.environ.get("STORE", "store.json")
LOCK = threading.Lock()
STATE = {"next": 1, "todos": []}

try:
    with open(STORE, "r", encoding="utf-8") as f:
        _d = json.load(f)
    if isinstance(_d, dict) and isinstance(_d.get("todos"), list):
        STATE["todos"] = _d["todos"]
        STATE["next"] = int(_d.get("next", 1))
except Exception:
    pass


def save():
    tmp = STORE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(STATE, f)
    os.replace(tmp, STORE)


def find(i):
    for t in STATE["todos"]:
        if t["id"] == i:
            return t
    return None


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj=None):
        if obj is None:
            self.send_response(code)
            self.send_header("Content-Length", "0")
            self.end_headers()
            return
        body = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def nf(self):
        self.send(404, {"error": "not found"})

    def body(self):
        try:
            n = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            n = 0
        return self.rfile.read(n) if n > 0 else b""

    def handle_any(self):
        method = self.command
        raw = self.body() if method in ("POST", "PATCH", "PUT", "DELETE") else b""
        u = urlsplit(self.path)
        path = u.path
        with LOCK:
            if path == "/todos":
                if method == "GET":
                    q = parse_qs(u.query)
                    items = list(STATE["todos"])
                    v = q.get("done", [None])[0]
                    if v == "true":
                        items = [t for t in items if t["done"] is True]
                    elif v == "false":
                        items = [t for t in items if t["done"] is False]
                    return self.send(200, items)
                if method == "POST":
                    try:
                        d = json.loads(raw)
                    except Exception:
                        d = None
                    title = d.get("title") if isinstance(d, dict) else None
                    if not isinstance(title, str) or not title.strip():
                        return self.send(400, {"error": "title required"})
                    t = {"id": STATE["next"], "title": title.strip(), "done": False}
                    STATE["next"] += 1
                    STATE["todos"].append(t)
                    save()
                    return self.send(201, t)
                return self.nf()
            m = re.fullmatch(r"/todos/([0-9]+)", path)
            if not m or str(int(m.group(1))) != m.group(1):
                return self.nf()
            t = find(int(m.group(1)))
            if t is None:
                return self.nf()
            if method == "GET":
                return self.send(200, t)
            if method == "DELETE":
                STATE["todos"].remove(t)
                save()
                return self.send(204)
            if method == "PATCH":
                try:
                    d = json.loads(raw)
                except Exception:
                    d = None
                bad = {"error": "bad update"}
                if not isinstance(d, dict):
                    return self.send(400, bad)
                if "title" in d:
                    if not isinstance(d["title"], str) or not d["title"].strip():
                        return self.send(400, bad)
                if "done" in d and not isinstance(d["done"], bool):
                    return self.send(400, bad)
                if "title" in d:
                    t["title"] = d["title"].strip()
                if "done" in d:
                    t["done"] = d["done"]
                save()
                return self.send(200, t)
            return self.nf()

    do_GET = do_POST = do_PATCH = do_DELETE = do_PUT = handle_any
    do_HEAD = do_OPTIONS = handle_any


class S(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True


if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8000"))
    S(("127.0.0.1", port), H).serve_forever()

import os, re, json, sqlite3, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

conn = sqlite3.connect(os.environ["DB"], check_same_thread=False, isolation_level=None)
conn.execute("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)")
lock = threading.Lock()

ID_RE = re.compile(r"^/notes/([0-9]+)$")


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj):
        data = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def nf(self):
        self.send(404, {"error": "not found"})

    def handle_any(self):
        try:
            n = int(self.headers.get("content-length") or 0)
        except ValueError:
            n = 0
        raw = self.rfile.read(n) if n > 0 else b""
        sp = urlsplit(self.path)
        path = sp.path
        m = self.command
        idm = ID_RE.match(path)
        with lock:
            if path == "/notes" and m == "POST":
                return self.create(raw)
            if path == "/notes" and m == "GET":
                return self.listing(sp.query)
            if idm and m == "GET":
                r = conn.execute("SELECT id,title,body,tags FROM notes WHERE id=?", (int(idm.group(1)),)).fetchone()
                if not r:
                    return self.nf()
                return self.send(200, {"id": r[0], "title": r[1], "body": r[2], "tags": json.loads(r[3])})
            if idm and m == "DELETE":
                i = int(idm.group(1))
                c = conn.execute("DELETE FROM notes WHERE id=?", (i,))
                if c.rowcount == 0:
                    return self.nf()
                return self.send(200, {"deleted": i})
        self.nf()

    def create(self, raw):
        bad = {"error": "invalid note"}
        try:
            d = json.loads(raw.decode())
        except Exception:
            return self.send(400, bad)
        if not isinstance(d, dict):
            return self.send(400, bad)
        t, b = d.get("title"), d.get("body")
        tags = d.get("tags", [])
        if not isinstance(t, str) or not t or not isinstance(b, str):
            return self.send(400, bad)
        if not isinstance(tags, list) or not all(isinstance(x, str) for x in tags):
            return self.send(400, bad)
        out = []
        for x in tags:
            x = x.lower()
            if x not in out:
                out.append(x)
        c = conn.execute("INSERT INTO notes(title,body,tags) VALUES(?,?,?)", (t, b, json.dumps(out)))
        self.send(201, {"id": c.lastrowid})

    def listing(self, query):
        qs = parse_qs(query)
        tag = qs.get("tag", [None])[0]
        q = qs.get("q", [None])[0]
        if tag is not None:
            tag = tag.lower()
        res = []
        for i, t, b, tg in conn.execute("SELECT id,title,body,tags FROM notes ORDER BY id DESC"):
            if tag is not None and tag not in json.loads(tg):
                continue
            if q is not None and q not in t and q not in b:
                continue
            res.append({"id": i, "title": t})
        self.send(200, res)


for _m in ("GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS"):
    setattr(H, "do_" + _m, H.handle_any)

ThreadingHTTPServer(("127.0.0.1", int(os.environ["PORT"])), H).serve_forever()

import json
import os
import sys
import urllib.request
import urllib.error

base = os.environ["API"].rstrip("/")


def request(req):
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, r.read()
    except urllib.error.HTTPError as e:
        return e.code, e.read()


def main():
    orders = []
    page = 1
    seen = set()
    while page is not None:
        if page in seen:
            sys.exit("pagination loop")
        seen.add(page)
        status, body = request(urllib.request.Request(f"{base}/orders?page={page}"))
        if status != 200:
            sys.exit(f"GET page {page} failed: {status}")
        data = json.loads(body)
        orders.extend(data.get("orders", []))
        page = data.get("next")

    paid_cents = {}
    refunded = 0
    largest = None
    best = None
    for o in orders:
        st = o.get("status")
        if st == "paid":
            c = o["cents"]
            cur = o["currency"]
            paid_cents[cur] = paid_cents.get(cur, 0) + c
            if best is None or c > best or (c == best and o["id"] < largest):
                best = c
                largest = o["id"]
        elif st == "refunded":
            refunded += 1

    summary = {
        "orders": len(orders),
        "paid_cents": paid_cents,
        "refunded": refunded,
        "largest": largest,
    }
    req = urllib.request.Request(
        f"{base}/summaries",
        data=json.dumps(summary).encode(),
        method="POST",
        headers={"content-type": "application/json"},
    )
    status, body = request(req)
    if status != 201:
        sys.exit(f"POST failed: {status}")
    print(json.loads(body)["id"])


