import os, json, sys

def key(s):
    return s.encode("utf-8", "surrogatepass")

def main():
    path = os.path.join(os.environ["INPUT"], "packages.json")
    try:
        with open(path, "rb") as f:
            data = json.loads(f.read().decode("utf-8"))
    except Exception:
        print("error: not an object")
        return
    if not isinstance(data, dict):
        print("error: not an object")
        return
    valid = {}
    invalid = []
    for k, v in data.items():
        if isinstance(v, list) and all(isinstance(x, str) for x in v):
            valid[k] = set(v)
        else:
            invalid.append(k)
    names = sorted(valid, key=key)
    out = []

    # stages
    built = {}
    remaining = set(valid)
    stage = 0
    while True:
        stage += 1
        cur = [p for p in remaining
               if all(d in built for d in valid[p])]
        if not cur:
            break
        for p in cur:
            built[p] = stage
        remaining -= set(cur)
    by_stage = {}
    for p, s in built.items():
        by_stage.setdefault(s, []).append(p)
    for s in sorted(by_stage):
        out.append("stage %d: %s" % (s, ", ".join(sorted(by_stage[s], key=key))))

    # Tarjan iterative
    index = {}
    low = {}
    onstack = set()
    stack = []
    sccs = []
    counter = 0
    for root in names:
        if root in index:
            continue
        index[root] = low[root] = counter
        counter += 1
        stack.append(root)
        onstack.add(root)
        work = [(root, iter(sorted((d for d in valid[root] if d in valid), key=key)))]
        while work:
            v, it = work[-1]
            advanced = False
            for w in it:
                if w not in index:
                    index[w] = low[w] = counter
                    counter += 1
                    stack.append(w)
                    onstack.add(w)
                    work.append((w, iter(sorted((d for d in valid[w] if d in valid), key=key))))
                    advanced = True
                    break
                elif w in onstack:
                    low[v] = min(low[v], index[w])
            if advanced:
                continue
            work.pop()
            if work:
                u = work[-1][0]
                low[u] = min(low[u], low[v])
            if low[v] == index[v]:
                comp = []
                while True:
                    w = stack.pop()
                    onstack.discard(w)
                    comp.append(w)
                    if w == v:
                        break
                sccs.append(comp)
    groups = []
    incycle = set()
    for c in sccs:
        if len(c) >= 2 or (c[0] in valid[c[0]]):
            groups.append(sorted(c, key=key))
            incycle.update(c)
    groups.sort(key=lambda g: key(g[0]))
    for g in groups:
        out.append("cycle: " + ", ".join(g))

    missing = {}
    for p in names:
        for d in valid[p]:
            if d not in valid:
                missing.setdefault(d, []).append(p)
    for m in sorted(missing, key=key):
        out.append("missing: %s (needed by %s)" % (m, ", ".join(sorted(missing[m], key=key))))

    if invalid:
        out.append("invalid: " + ", ".join(sorted(invalid, key=key)))

    blocked = [p for p in names if p not in built and p not in incycle]
    if blocked:
        out.append("blocked: " + ", ".join(blocked))
    out.append("built %d of %d" % (len(built), len(valid)))
    print("\n".join(out))

