import os, re, sys

def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "bookings.csv"), "rb") as f:
        text = f.read().decode("utf-8", errors="replace")
    lines = text.split("\n")
    tre = re.compile(r"^[0-9][0-9]:[0-9][0-9]$")

    def parse(t):
        if not tre.match(t):
            return None
        h = int(t[:2]); m = int(t[3:])
        if m > 59:
            return None
        if h > 24 or (h == 24 and m != 0):
            return None
        return h * 60 + m

    def fmt(x):
        return "%02d:%02d" % (x // 60, x % 60)

    skipped = []
    seen = set()
    data = {}
    for i, raw in enumerate(lines):
        n = i + 1
        if n == 1:
            continue
        line = raw[:-1] if raw.endswith("\r") else raw
        if line.strip() == "":
            continue
        parts = line.split(",")
        if len(parts) != 5:
            skipped.append(n)
            continue
        room, day, st, en, who = parts
        s = parse(st); e = parse(en)
        if s is None or e is None or e <= s:
            skipped.append(n)
            continue
        key = tuple(parts)
        if key in seen:
            continue
        seen.add(key)
        data.setdefault(room, {}).setdefault(day, []).append((s, e, who))

    out = []
    for room in sorted(data):
        for day in sorted(data[room]):
            bs = data[room][day]
            out.append("%s %s" % (room, day))
            merged = []
            for s, e, _ in sorted(bs):
                if merged and s <= merged[-1][1]:
                    if e > merged[-1][1]:
                        merged[-1][1] = e
                else:
                    merged.append([s, e])
            out.append("  busy " + ", ".join("%s-%s" % (fmt(s), fmt(e)) for s, e in merged))
            free = []
            cur = 540
            for s, e in merged:
                if e <= 540:
                    continue
                if s >= 1080:
                    break
                if s - cur >= 30:
                    free.append((cur, s))
                cur = max(cur, e)
            if 1080 - cur >= 30:
                free.append((cur, 1080))
            if free:
                out.append("  free " + ", ".join("%s-%s" % (fmt(s), fmt(e)) for s, e in free))
            else:
                out.append("  free none")
            confs = []
            for a in range(len(bs)):
                for b in range(a + 1, len(bs)):
                    lo = max(bs[a][0], bs[b][0])
                    hi = min(bs[a][1], bs[b][1])
                    if lo < hi:
                        w = sorted([bs[a][2], bs[b][2]], key=lambda x: x.encode("utf-8"))
                        txt = "conflict %s/%s %s-%s" % (w[0], w[1], fmt(lo), fmt(hi))
                        confs.append((lo, txt))
            confs.sort(key=lambda c: (c[0], c[1].encode("utf-8")))
