import os, re, sys

def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "bookings.csv"), "rb") as f:
        text = f.read().decode("utf-8", "replace")
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    pat = re.compile(r"^[0-9][0-9]:[0-9][0-9]$")

    def parse(t, is_end):
        if not pat.match(t):
            return None
        h, m = int(t[:2]), int(t[3:])
        if m > 59:
            return None
        if h == 24 and m == 0 and is_end:
            return 1440
        if h > 23:
            return None
        return h * 60 + m

    def fmt(x):
        return "%02d:%02d" % (x // 60, x % 60)

    skipped = []
    seen = set()
    data = {}
    for i, line in enumerate(lines):
        n = i + 1
        if n == 1:
            continue
        line = line.rstrip("\r")
        if line.strip() == "":
            continue
        p = line.split(",")
        if len(p) != 5:
            skipped.append(n)
            continue
        s = parse(p[2], False)
        e = parse(p[3], True)
        if s is None or e is None or e <= s:
            skipped.append(n)
            continue
        key = tuple(p)
        if key in seen:
            continue
        seen.add(key)
        data.setdefault(p[0], {}).setdefault(p[1], []).append((s, e, p[4]))

    out = []
    for room in sorted(data):
        for day in sorted(data[room]):
            bs = data[room][day]
            out.append("%s %s" % (room, day))
            merged = []
            for s, e, _ in sorted(bs):
                if merged and s <= merged[-1][1]:
                    if e > merged[-1][1]:
                        merged[-1][1] = e
                else:
                    merged.append([s, e])
            out.append("  busy " + ", ".join("%s-%s" % (fmt(s), fmt(e)) for s, e in merged))
            gaps = []
            cur = 540
            for s, e in merged:
                if e <= cur:
                    continue
                end = min(s, 1080)
                if end - cur >= 30:
                    gaps.append((cur, end))
                cur = max(cur, e)
            if cur < 1080 and 1080 - cur >= 30:
                gaps.append((cur, 1080))
            if gaps:
                out.append("  free " + ", ".join("%s-%s" % (fmt(s), fmt(e)) for s, e in gaps))
            else:
                out.append("  free none")
            conf = []
            for a in range(len(bs)):
                for b in range(a + 1, len(bs)):
                    s = max(bs[a][0], bs[b][0])
                    e = min(bs[a][1], bs[b][1])
                    if e > s:
                        x, y = sorted([bs[a][2], bs[b][2]], key=lambda w: w.encode("utf-8"))
                        conf.append((s, "%s/%s %s-%s" % (x, y, fmt(s), fmt(e))))
            conf.sort(key=lambda c: (c[0], c[1].encode("utf-8")))
            for _, t in conf:
                out.append("  conflict " + t)
    out.append("skipped: " + (", ".join(map(str, skipped)) if skipped else "none"))
    sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8"))

