import os, json, sys

class F(float):
    pass

def bad_const(s):
    raise ValueError(s)

def check(v, sc, path, errs):
    t = sc.get("type")
    if t == "object":
        ok = isinstance(v, dict)
    elif t == "array":
        ok = isinstance(v, list)
    elif t == "string":
        ok = isinstance(v, str)
    elif t == "integer":
        ok = isinstance(v, int) and not isinstance(v, bool)
    elif t == "number":
        ok = isinstance(v, (int, float)) and not isinstance(v, bool)
    elif t == "boolean":
        ok = isinstance(v, bool)
    elif t == "null":
        ok = v is None
    else:
        ok = True
    if not ok:
        errs.append((path, "expected " + str(t)))
        return
    if t == "object":
        props = sc.get("properties", {})
        for r in sc.get("required", []):
            if r not in v:
                errs.append((path + "." + r, "missing required field"))
        if sc.get("additional", True) is False:
            for k in v:
                if k not in props:
                    errs.append((path + "." + k, "unexpected field"))
        for k, s in props.items():
            if k in v:
                check(v[k], s, path + "." + k, errs)
    elif t == "array":
        mi = sc.get("min_items")
        if mi is not None and len(v) < mi:
            errs.append((path, "fewer than %d items" % mi))
        if "items" in sc:
            for i, e in enumerate(v):
                check(e, sc["items"], "%s[%d]" % (path, i), errs)
    elif t == "string":
        n = len(v)
        if "min_length" in sc and n < sc["min_length"]:
            errs.append((path, "shorter than %d" % sc["min_length"]))
        elif "max_length" in sc and n > sc["max_length"]:
            errs.append((path, "longer than %d" % sc["max_length"]))
        elif "enum" in sc and v not in sc["enum"]:
            errs.append((path, "not in enum"))
    elif t in ("integer", "number"):
        if "minimum" in sc and v < sc["minimum"]:
            errs.append((path, "less than %d" % sc["minimum"]))
        elif "maximum" in sc and v > sc["maximum"]:
            errs.append((path, "greater than %d" % sc["maximum"]))

def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "schema.json"), "rb") as f:
        schema = json.loads(f.read().decode("utf-8"))
    with open(os.path.join(d, "records.jsonl"), "rb") as f:
        data = f.read()
    out = []
    valid = 0
    total = 0
    for n, raw in enumerate(data.split(b"\n"), 1):
        if raw.strip(b" \t\r") == b"":
            continue
        total += 1
        try:
            line = raw.decode("utf-8")
            rec = json.loads(line, parse_float=F, parse_constant=bad_const)
        except Exception:
            out.append("line %d: invalid JSON" % n)
            continue
        errs = []
        check(rec, schema, "$", errs)
        if not errs:
            valid += 1
            out.append("line %d: ok" % n)
        else:
            errs = sorted(set(errs), key=lambda e: (e[0].encode("utf-8", "surrogatepass"), e[1].encode("utf-8", "surrogatepass")))
            for p, m in errs:
                out.append("line %d: %s: %s" % (n, p, m))
    out.append("valid %d of %d" % (valid, total))
    sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8", "surrogatepass"))

