import json
import os
import urllib.request
import urllib.error
import urllib.parse


def main():
    inp = os.environ["INPUT"]
    state_path = os.environ["STATE"]
    api = os.environ["API"].rstrip("/")

    state = {}
    try:
        with open(state_path, "r", encoding="utf-8") as f:
            state = json.load(f)
        if not isinstance(state, dict):
            state = {}
    except (OSError, ValueError):
        state = {}

    with open(os.path.join(inp, "records.jsonl"), "rb") as f:
        text = f.read().decode("utf-8", errors="replace")

    out = []
    records = {}
    for n, line in enumerate(text.split("\n"), 1):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        ok = False
        try:
            obj = json.loads(line)
            if (isinstance(obj, dict) and isinstance(obj.get("id"), str)
                    and isinstance(obj.get("version"), int)
                    and not isinstance(obj.get("version"), bool)):
                ok = True
        except ValueError:
            pass
        if ok:
            records[obj["id"]] = obj
        else:
            out.append("line %d invalid" % n)

    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}

    for rid in sorted(records, key=lambda s: s.encode("utf-8")):
        obj = records[rid]
        last = state.get(rid)
        if isinstance(last, int) and obj["version"] <= last:
            out.append("%s unchanged" % rid)
            counts["unchanged"] += 1
            continue
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        url = api + "/records/" + urllib.parse.quote(rid, safe="")
        result = "failed"
        for _ in range(3):
            req = urllib.request.Request(
                url, data=body, method="PUT",
                headers={"content-type": "application/json"})
            status = None
            try:
                with urllib.request.urlopen(req, timeout=30) as r:
                    status = r.status
            except urllib.error.HTTPError as e:
                status = e.code
            except Exception:
                status = None
            if status is not None and 200 <= status < 300:
                state[rid] = obj["version"]
                result = "synced"
                break
            if status is not None and 400 <= status < 500:
                result = "rejected %d" % status
                break
        if result == "synced":
            counts["synced"] += 1
        elif result == "failed":
            counts["failed"] += 1
        else:
            counts["rejected"] += 1
        out.append("%s %s" % (rid, result))

    with open(state_path, "w", encoding="utf-8") as f:
        json.dump(state, f)

    out.append("synced %d unchanged %d rejected %d failed %d" % (
        counts["synced"], counts["unchanged"], counts["rejected"], counts["failed"]))
    print("\n".join(out))


