        text = ""

    out = []
    recs = {}
    for n, line in enumerate(text.split("\n"), 1):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        try:
            o = json.loads(line)
        except Exception:
            o = None
        if (not isinstance(o, dict) or not isinstance(o.get("id"), str)
                or not isinstance(o.get("version"), int)
                or isinstance(o.get("version"), bool)):
            out.append("line %d invalid" % n)
            continue
        recs[o["id"]] = o

    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}

    def push(o):
        body = json.dumps(o).encode("utf-8")
        url = api + "/records/" + urllib.parse.quote(o["id"], safe="")
        for _ in range(3):
            req = urllib.request.Request(
                url, data=body, method="PUT",
                headers={"content-type": "application/json"})
            try:
                with urllib.request.urlopen(req, timeout=15) as r:
                    st = r.status
            except urllib.error.HTTPError as e:
                st = e.code
            except Exception:
                continue
            if 200 <= st < 300:
                return "synced", st
            if 400 <= st < 500:
                return "rejected", st
        return "failed", None

