import os, sys, re, sqlite3, datetime

MAXV = 9223372036854775807
INT = re.compile(r"^-?[0-9]+$")


def main():
    inp = os.environ["INPUT"]
    dbp = os.environ["DB"]
    logp = os.environ["LOG"]
    ms = int(os.environ["CLOCK"])
    t = datetime.datetime.fromtimestamp(ms // 1000, datetime.timezone.utc)
    ts = t.strftime("%Y-%m-%dT%H:%M:%SZ")

    def fmt(m):
        return datetime.datetime.fromtimestamp(m // 1000, datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

    con = sqlite3.connect(dbp)
    con.execute("CREATE TABLE IF NOT EXISTS accounts(name TEXT PRIMARY KEY, balance INTEGER NOT NULL, closed INTEGER NOT NULL, last INTEGER NOT NULL)")
    con.execute("CREATE TABLE IF NOT EXISTS transfers(id TEXT PRIMARY KEY, src TEXT NOT NULL, dst TEXT NOT NULL, cents INTEGER NOT NULL)")
    con.commit()

    with open(os.path.join(inp, "ops.txt"), "rb") as f:
        data = f.read()
    lines = data.split(b"\n")
    if lines and lines[-1] == b"":
        lines.pop()

    ok = failed = dup = 0
    logs = []

    def get(name):
        r = con.execute("SELECT balance, closed FROM accounts WHERE name=?", (name,)).fetchone()
        return r

    for i, raw in enumerate(lines, 1):
        line = raw.decode("latin-1")
        if line.endswith("\r"):
            line = line[:-1]
        if line == "":
            continue
        w = line.split(" ")
        err = None
        op = w[0]
        if op == "open" and len(w) == 3 and INT.match(w[2]):
            name = w[1]
            amt = int(w[2])
            if amt < 0 or amt > MAXV:
                err = "bad amount"
            elif get(name) is not None:
                err = "account exists"
            else:
                con.execute("INSERT INTO accounts VALUES(?,?,0,?)", (name, amt, ms))
        elif op == "transfer" and len(w) == 5 and INT.match(w[4]):
            tid, src, dst = w[1], w[2], w[3]
            amt = int(w[4])
            prev = con.execute("SELECT src,dst,cents FROM transfers WHERE id=?", (tid,)).fetchone()
            if prev is not None:
                if prev == (src, dst, amt):
                    dup += 1
                    continue
                err = "id reused"
            elif amt <= 0:
                err = "bad amount"
            elif src == dst:
                err = "same account"
            else:
                a = get(src)
                if a is None or a[1]:
                    err = "no account " + src
                else:
                    b = get(dst)
                    if b is None or b[1]:
                        err = "no account " + dst
                    elif a[0] < amt:
                        err = "insufficient funds"
                    elif b[0] + amt > MAXV:
                        err = "overflow"
                    else:
                        con.execute("UPDATE accounts SET balance=?, last=? WHERE name=?", (a[0] - amt, ms, src))
                        con.execute("UPDATE accounts SET balance=?, last=? WHERE name=?", (b[0] + amt, ms, dst))
                        con.execute("INSERT INTO transfers VALUES(?,?,?,?)", (tid, src, dst, amt))
        elif op == "close" and len(w) == 2:
            a = get(w[1])
            if a is None or a[1]:
                err = "no account " + w[1]
            elif a[0] != 0:
                err = "balance not zero"
            else:
                con.execute("UPDATE accounts SET closed=1, last=? WHERE name=?", (ms, w[1]))
        else:
            err = "malformed"
        if err:
            failed += 1
            logs.append("%s line %d: %s\n" % (ts, i, err))
        else:
            ok += 1

    con.commit()
    rows = con.execute("SELECT name, balance, last FROM accounts WHERE closed=0").fetchall()
    con.close()
    rows.sort(key=lambda r: r[0].encode("latin-1"))

    if logs:
        with open(logp, "ab") as f:
            f.write("".join(logs).encode("latin-1"))

    out = "ok %d failed %d duplicate %d\n" % (ok, failed, dup)
    for n, b, l in rows:
        out += "%s %d last %s\n" % (n, b, fmt(l))
    sys.stdout.buffer.write(out.encode("latin-1"))
    sys.stdout.buffer.flush()


main()

