    tmp = KV + ".tmp"
    with open(tmp, "w") as f:
        json.dump(DB, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, KV)


def now():
    try:
        return int(os.environ["CLOCK"])
    except Exception:
        return int(time.time() * 1000)


def h(salt, pw):
    return hashlib.sha256(salt.encode() + pw.encode("utf-8", "surrogatepass")).hexdigest()


