import os, json, re, sqlite3, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

LOCK = threading.Lock()
conn = sqlite3.connect(os.environ["DB"], check_same_thread=False, isolation_level=None)
conn.execute("PRAGMA journal_mode=WAL")
conn.execute("PRAGMA synchronous=FULL")
conn.execute("""CREATE TABLE IF NOT EXISTS payments(
  n INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL,
  currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)""")
conn.execute("""CREATE TABLE IF NOT EXISTS idem(
  k TEXT PRIMARY KEY, method TEXT, path TEXT, body TEXT, status INTEGER, resp TEXT)""")

BAD = object()


def pay(r):
    return {"id": "pay_%d" % r[0], "account": r[1], "cents": r[2],
            "currency": r[3], "status": r[4], "refunded": r[5]}


def getpay(n):
    return conn.execute("SELECT n,account,cents,currency,status,refunded FROM payments WHERE n=?", (n,)).fetchone()


def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def canon(v):
    return json.dumps(v, sort_keys=True, separators=(",", ":"))


def route(method, rawpath, headers, raw):
    sp = urlsplit(rawpath)
    path = sp.path
    nf = (404, {"error": "not found"})
    m = re.fullmatch(r"/payments/pay_([1-9][0-9]*)(?:/(capture|cancel|refund))?", path)
    if method == "GET":
        if path == "/payments":
            acc = parse_qs(sp.query).get("account", [None])[0]
            rows = conn.execute("SELECT n,account,cents,currency,status,refunded FROM payments WHERE account=? ORDER BY n", (acc,)).fetchall()
            return 200, [pay(r) for r in rows]
        if m and not m.group(2):
            r = getpay(int(m.group(1)))
            return (200, pay(r)) if r else nf
        return nf
    if method != "POST":
        return nf
    is_create = path == "/payments"
    is_refund = bool(m and m.group(2) == "refund")
    try:
        body = json.loads(raw.decode("utf-8")) if raw else BAD
    except Exception:
        body = BAD
    key = None
    if is_create or is_refund:
        key = headers.get("idempotency-key")
        if not key:
            return 400, {"error": "missing idempotency key"}
        row = conn.execute("SELECT method,path,body,status,resp FROM idem WHERE k=?", (key,)).fetchone()
        if row:
            cb = None if body is BAD else canon(body)
            if row[0] == method and row[1] == path and row[2] == cb:
                return row[3], json.loads(row[4])
            return 409, {"error": "key reused"}
    if is_create:
        ok = (isinstance(body, dict) and set(body) == {"account", "cents", "currency"}
              and isinstance(body["account"], str) and body["account"] != ""
              and is_int(body["cents"]) and body["cents"] > 0
              and body["currency"] in ("EUR", "USD"))
        if not ok:
            return 422, {"error": "invalid payment"}
        cur = conn.execute("INSERT INTO payments(account,cents,currency,status,refunded) VALUES(?,?,?,?,0)",
                           (body["account"], body["cents"], body["currency"], "pending"))
        result = (201, pay(getpay(cur.lastrowid)))
    elif m and m.group(2):
        n = int(m.group(1))
        r = getpay(n)
        if not r:
            return nf
        act = m.group(2)
        if act == "capture":
            if r[4] == "pending":
                conn.execute("UPDATE payments SET status='captured' WHERE n=?", (n,))
            elif r[4] != "captured":
                return 409, {"error": "invalid transition"}
            return 200, pay(getpay(n))
        if act == "cancel":
            if r[4] != "pending":
                return 409, {"error": "invalid transition"}
            conn.execute("UPDATE payments SET status='canceled' WHERE n=?", (n,))
            return 200, pay(getpay(n))
        if not (isinstance(body, dict) and set(body) == {"cents"} and is_int(body["cents"]) and body["cents"] > 0):
            return 422, {"error": "invalid refund"}
        if r[4] != "captured":
            return 409, {"error": "invalid transition"}
        tot = r[5] + body["cents"]
        if tot > r[2]:
            return 409, {"error": "exceeds captured"}
        st = "refunded" if tot == r[2] else "captured"
        conn.execute("UPDATE payments SET refunded=?, status=? WHERE n=?", (tot, st, n))
        result = (200, pay(getpay(n)))
    else:
        return nf
    if key is not None and 200 <= result[0] < 300:
        conn.execute("INSERT INTO idem(k,method,path,body,status,resp) VALUES(?,?,?,?,?,?)",
                     (key, method, path, canon(body), result[0], json.dumps(result[1])))
    return result


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def handle_any(self):
        try:
            ln = int(self.headers.get("content-length") or 0)
        except ValueError:
            ln = 0
        raw = self.rfile.read(ln) if ln > 0 else b""
        hd = {"idempotency-key": self.headers.get("idempotency-key")}
        with LOCK:
            try:
                conn.execute("BEGIN IMMEDIATE")
                status, obj = route(self.command, self.path, hd, raw)
                conn.execute("COMMIT")
            except Exception:
                try:
                    conn.execute("ROLLBACK")
                except Exception:
                    pass
                status, obj = 500, {"error": "internal error"}
        data = json.dumps(obj).encode()
        self.send_response(status)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = handle_any


class S(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True


S(("127.0.0.1", int(os.environ["PORT"])), H).serve_forever()

import os, re

def parse(text):
    recs = []
    fields = []
    cur = []
    state = 0
    bad = False
    n = len(text)
    i = 0

    def emit():
        nonlocal fields, cur, state, bad
        fields.append("".join(cur))
        recs.append((fields, bad))
        fields = []
        cur = []
        state = 0
        bad = False

    while i < n:
        c = text[i]
        nxt = text[i + 1] if i + 1 < n else ""
        if state == 2:
            if c == '"':
                if nxt == '"':
                    cur.append('"')
                    i += 2
                    continue
                state = 3
            else:
                cur.append(c)
            i += 1
            continue
        if c == ',':
            fields.append("".join(cur))
            cur = []
            state = 0
        elif c == '\n' or (c == '\r' and nxt == '\n'):
            empty = (not fields and not cur and state == 0)
            if c == '\r':
                i += 1
            if not empty:
                emit()
        elif c == '"':
            if state == 0:
                state = 2
            else:
                bad = True
                cur.append(c)
                state = 1
        else:
            if state == 3:
                bad = True
                state = 1
            elif state == 0:
                state = 1
            cur.append(c)
        i += 1
    if state == 2:
        bad = True
        emit()
    elif not (not fields and not cur and state == 0):
        emit()
    return recs

def q(f):
    if any(ch in f for ch in ',"\r\n'):
        return '"' + f.replace('"', '""') + '"'
    return f

def money(c):
    s = "-" if c < 0 else ""
    c = abs(c)
    return "%s%d.%02d" % (s, c // 100, c % 100)

def main():
    inp = os.environ["INPUT"]
    out = os.environ["OUT"]
    with open(os.path.join(inp, "sales.csv"), "rb") as f:
        text = f.read().decode("utf-8", "surrogateescape")
    recs = parse(text)
    body = recs[1:]
    lines = ["region,product,qty,price,note\n"]
    badlist = []
    regions = {}
    for idx, (fl, bad) in enumerate(body, 1):
        ok = False
        if not bad and len(fl) == 5:
            r, p, qty, price, note = fl
            if (r and p and re.fullmatch(r"-?[0-9]+", qty)
                    and re.fullmatch(r"[0-9]+(\.[0-9]{1,2})?", price)):
                ok = True
        if not ok:
            badlist.append(idx)
            continue
        if "." in price:
            a, b = price.split(".")
            cents = int(a) * 100 + int(b.ljust(2, "0"))
        else:
            cents = int(price) * 100
        lines.append(",".join(q(x) for x in (r, p, qty, money(cents), note)) + "\n")
        qn = int(qty)
        d = regions.setdefault(r, [0, 0, {}])
        d[0] += qn * cents
        d[1] += qn
        d[2][p] = d[2].get(p, 0) + qn * cents
    with open(os.path.join(out, "clean.csv"), "w", encoding="utf-8",
              errors="surrogateescape", newline="") as f:
        f.write("".join(lines))
    for r in sorted(regions, key=lambda s: s.encode("utf-8", "surrogateescape")):
        rev, items, prods = regions[r]
        top = min(prods, key=lambda p: (-prods[p], p.encode("utf-8", "surrogateescape")))
        print("%s revenue %s items %d top %s" % (r, money(rev), items, top))
    if badlist:
        print("records %d bad %d: %s" % (len(body), len(badlist), ", ".join(map(str, badlist))))
    else:
        print("records %d bad 0" % len(body))

main()

import os, re, json, hashlib

WORD = re.compile(rb'[0-9A-Za-z\x80-\xff]+')


def words_of(data):
    return {w.decode('utf-8', 'replace').lower() for w in WORD.findall(data)}


def main():
    docs = os.environ['DOCS']
    qdir = os.environ['QUERIES']
    kv = os.environ['INDEX']

    old = {}
    try:
        with open(kv, 'r', encoding='utf-8') as f:
            old = json.load(f).get('files', {})
    except (OSError, ValueError, AttributeError):
        old = {}

    cur = {}
    for root, dirs, files in os.walk(docs):
        for fn in files:
            full = os.path.join(root, fn)
            rel = os.path.relpath(full, docs).replace(os.sep, '/')
            try:
                with open(full, 'rb') as f:
                    data = f.read()
            except OSError:
                continue
            h = hashlib.sha256(data).hexdigest()
            o = old.get(rel)
            if o is not None and o.get('hash') == h:
                cur[rel] = o
                cur[rel]['_status'] = 'same'
            else:
                cur[rel] = {'hash': h, 'words': sorted(words_of(data)),
                            '_status': 'changed' if o is not None else 'added'}

    def key(p):
        return p.encode('utf-8', 'surrogateescape')

    out = []
    unchanged = 0
    events = []
    for p in cur:
        s = cur[p]['_status']
        if s == 'same':
            unchanged += 1
        else:
            events.append((p, s))
    for p in old:
        if p not in cur:
            events.append((p, 'removed'))
    events.sort(key=lambda e: key(e[0]))
    for p, s in events:
        out.append('%s %s' % (s, p))
    out.append('unchanged %d' % unchanged)

    # inverted index word -> paths
    inv = {}
    for p, v in cur.items():
        for w in v['words']:
            inv.setdefault(w, set()).add(p)

    saved = {p: {'hash': v['hash'], 'words': v['words']} for p, v in cur.items()}
    tmp = kv + '.tmp'
    with open(tmp, 'w', encoding='utf-8') as f:
        json.dump({'files': saved, 'inv': {w: sorted(s) for w, s in inv.items()}}, f)
    os.replace(tmp, kv)

    allpaths = set(cur)
    try:
        with open(os.path.join(qdir, 'queries.txt'), 'rb') as f:
            text = f.read().decode('utf-8', 'replace')
    except OSError:
        text = ''
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if not line.strip():
            continue
        ws = words_of(line.encode('utf-8'))
        res = set(allpaths)
        for w in ws:
            res &= inv.get(w, set())
            if not res:
                break
        if res:
            out.append('%s: %s' % (line, ', '.join(sorted(res, key=key))))
        else:
            out.append('%s: none' % line)

    print('\n'.join(out))


main()

import os, sys, json, sqlite3, urllib.request, urllib.error, urllib.parse

def isint(x):
    return isinstance(x, int) and not isinstance(x, bool)

def main():
    base = os.environ["API"].rstrip("/")
    con = sqlite3.connect(os.environ["DB"], isolation_level=None)
    con.execute("CREATE TABLE IF NOT EXISTS items(sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL)")
    con.execute("CREATE TABLE IF NOT EXISTS versions(sku TEXT PRIMARY KEY, version INTEGER NOT NULL)")
    con.execute("CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT NOT NULL)")
    row = con.execute("SELECT v FROM meta WHERE k='cursor'").fetchone()
    cursor = row[0] if row else "0"

    pages = applied = stale = invalid = 0
    stop = None
    seen = set()
    while True:
        seen.add(cursor)
        url = base + "/changes?cursor=" + urllib.parse.quote(cursor, safe="")
        try:
            with urllib.request.urlopen(url, timeout=30) as r:
                status = r.status
                body = r.read()
        except urllib.error.HTTPError as e:
            stop = "stopped at %s (status %d)" % (cursor, e.code)
            break
        except Exception:
            stop = "stopped at %s (no response)" % cursor
            break
        if status != 200:
            stop = "stopped at %s (status %d)" % (cursor, status)
            break
        try:
            data = json.loads(body.decode("utf-8"))
            if not isinstance(data, dict) or not isinstance(data.get("changes"), list):
                raise ValueError
            nxt = data.get("next")
            if nxt is not None:
                if isinstance(nxt, bool) or not isinstance(nxt, (str, int)):
                    raise ValueError
                nxt = str(nxt)
        except Exception:
            stop = "stopped at %s (invalid page)" % cursor
            break

        a = s = iv = 0
        con.execute("BEGIN")
        try:
            for c in data["changes"]:
                ok = False
                if isinstance(c, dict):
                    op = c.get("op")
                    if isinstance(c.get("sku"), str) and isint(c.get("version")):
                        if op == "upsert" and isinstance(c.get("name"), str) and isint(c.get("qty")):
                            ok = True
                        elif op == "delete":
                            ok = True
                if not ok:
                    iv += 1
                    continue
                sku, ver = c["sku"], c["version"]
                r = con.execute("SELECT version FROM versions WHERE sku=?", (sku,)).fetchone()
                if r is not None and ver <= r[0]:
                    s += 1
                    continue
                con.execute("INSERT OR REPLACE INTO versions(sku,version) VALUES(?,?)", (sku, ver))
                if c["op"] == "upsert":
                    con.execute("INSERT OR REPLACE INTO items(sku,name,qty) VALUES(?,?,?)",
                                (sku, c["name"], c["qty"]))
                else:
                    con.execute("DELETE FROM items WHERE sku=?", (sku,))
                a += 1
            newcur = cursor if (nxt is None or nxt in seen) else nxt
            con.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('cursor',?)", (newcur,))
            con.execute("COMMIT")
        except Exception:
            con.execute("ROLLBACK")
            raise
        pages += 1
        applied += a
        stale += s
        invalid += iv
        if nxt is None or nxt in seen:
            break
        cursor = nxt

    try:
        sys.stdout.reconfigure(encoding="utf-8")
    except Exception:
        pass
    print("pages %d applied %d stale %d invalid %d" % (pages, applied, stale, invalid))
    print(stop if stop else "complete")
    rows = con.execute("SELECT sku, qty, name FROM items").fetchall()
    rows.sort(key=lambda r: r[0].encode("utf-8", "surrogatepass"))
    for sku, qty, name in rows:
        print("%s %d %s" % (sku, qty, name))

main()

