    return isinstance(v, int) and not isinstance(v, bool)


def fetch(base, cursor):
    url = base.rstrip("/") + "/changes?cursor=" + urllib.parse.quote(cursor, safe="")
    req = urllib.request.Request(url, method="GET")
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            status = r.status
            body = r.read()
    except urllib.error.HTTPError as e:
        return ("status", e.code)
    except Exception:
        return ("noresp", None)
    if status != 200:
        return ("status", status)
    try:
        data = json.loads(body.decode("utf-8"))
    except Exception:
        return ("invalid", None)
    if not isinstance(data, dict) or not isinstance(data.get("changes"), list):
        return ("invalid", None)
    nxt = data.get("next")
    if nxt is not None:
        if isint(nxt) or isinstance(nxt, str):
            nxt = str(nxt)
        else:
            return ("invalid", None)
    return ("ok", (data["changes"], nxt))


def main():
    base = os.environ["API"]
    db = sqlite3.connect(os.environ["DB"], isolation_level=None)
    db.execute("CREATE TABLE IF NOT EXISTS items(sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL)")
    db.execute("CREATE TABLE IF NOT EXISTS versions(sku TEXT PRIMARY KEY, version INTEGER NOT NULL)")
    db.execute("CREATE TABLE IF NOT EXISTS state(k TEXT PRIMARY KEY, v TEXT NOT NULL)")
    row = db.execute("SELECT v FROM state WHERE k='cursor'").fetchone()
    cursor = row[0] if row else "0"

    pages = applied = stale = invalid = 0
    final = "complete"
    seen = set()
    while True:
        if cursor in seen:
            break
        seen.add(cursor)
        kind, val = fetch(base, cursor)
        if kind == "status":
            final = "stopped at %s (status %d)" % (cursor, val)
            break
        if kind == "noresp":
            final = "stopped at %s (no response)" % cursor
            break
        if kind == "invalid":
            final = "stopped at %s (invalid page)" % cursor
            break
        changes, nxt = val
        pa = ps = pi = 0
        db.execute("BEGIN")
        try:
            for c in changes:
                ok = False
                if isinstance(c, dict):
                    op = c.get("op")
                    sku = c.get("sku")
                    ver = c.get("version")
                    if isinstance(sku, str) and isint(ver):
                        if op == "upsert":
                            ok = isinstance(c.get("name"), str) and isint(c.get("qty"))
                        elif op == "delete":
                            ok = True
                if not ok:
                    pi += 1
                    continue
                r = db.execute("SELECT version FROM versions WHERE sku=?", (sku,)).fetchone()
                if r is not None and ver <= r[0]:
                    ps += 1
                    continue
                if op == "upsert":
                    db.execute("INSERT OR REPLACE INTO items(sku,name,qty) VALUES(?,?,?)",
                               (sku, c["name"], c["qty"]))
                else:
                    db.execute("DELETE FROM items WHERE sku=?", (sku,))
                db.execute("INSERT OR REPLACE INTO versions(sku,version) VALUES(?,?)", (sku, ver))
                pa += 1
            newcur = nxt if nxt is not None else cursor
            db.execute("INSERT OR REPLACE INTO state(k,v) VALUES('cursor',?)", (newcur,))
            db.execute("COMMIT")
        except Exception:
            db.execute("ROLLBACK")
            raise
        pages += 1
        applied += pa
        stale += ps
        invalid += pi
        if nxt is None:
            break
        cursor = nxt

    out = ["pages %d applied %d stale %d invalid %d" % (pages, applied, stale, invalid), final]
    rows = db.execute("SELECT sku,qty,name FROM items").fetchall()
    rows.sort(key=lambda r: r[0].encode("utf-8", "surrogatepass"))
    for sku, qty, name in rows:
        out.append("%s %d %s" % (sku, qty, name))
    sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8", "replace"))


