                s = 60 * (2 ** (j["attempts"] - 1))
                j["due"] = now + s * 1000
                print("retry %s in %d" % (i, s))
        else:
            j["state"] = "done"
            print("done " + i)

    c = {"pending": 0, "done": 0, "dead": 0}
    for j in jobs.values():
        c[j["state"]] += 1
    print("pending %d done %d dead %d" % (c["pending"], c["done"], c["dead"]))

    with open(qpath, "w", encoding="utf-8") as f:
        json.dump(jobs, f)

