import os, sys

sys.setrecursionlimit(100000)
LO, HI = -2**63, 2**63 - 1


class Syn(Exception):
    pass


class Err(Exception):
    pass


def tokenize(s):
    toks = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c in " \t\r\f\v":
            i += 1
        elif c in "0123456789":
            j = i
            while j < n and s[j] in "0123456789":
                j += 1
            toks.append(("int", int(s[i:j])))
            i = j
        elif (c.isascii() and c.isalpha()) or c == "_":
            j = i
            while j < n and s[j].isascii() and (s[j].isalnum() or s[j] == "_"):
                j += 1
            toks.append(("name", s[i:j]))
            i = j
        elif c in "+-*/%^(),=":
            toks.append(("op", c))
            i += 1
        else:
            raise Syn()
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.p = 0

    def peek(self):
        return self.t[self.p] if self.p < len(self.t) else (None, None)

    def isop(self, c):
        return self.peek() == ("op", c)

    def eat(self, c):
        if not self.isop(c):
            raise Syn()
        self.p += 1

    def expr(self):
        l = self.term()
        while self.isop("+") or self.isop("-"):
            o = self.peek()[1]
            self.p += 1
            l = ("bin", o, l, self.term())
        return l

    def term(self):
        l = self.factor()
        while self.peek()[0] == "op" and self.peek()[1] in "*/%":
            o = self.peek()[1]
            self.p += 1
            l = ("bin", o, l, self.factor())
        return l

    def factor(self):
        if self.isop("-"):
            self.p += 1
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.isop("^"):
            self.p += 1
            return ("bin", "^", a, self.factor())
        return a

    def atom(self):
        k, v = self.peek()
        if k == "int":
            self.p += 1
            return ("int", v)
        if k == "name":
            self.p += 1
            if self.isop("("):
                self.p += 1
                args = [self.expr()]
                while self.isop(","):
                    self.p += 1
                    args.append(self.expr())
                self.eat(")")
                return ("call", v, args)
            return ("var", v)
        if self.isop("("):
            self.p += 1
            e = self.expr()
            self.eat(")")
            return e
        raise Syn()


def chk(v):
    if v < LO or v > HI:
        raise Err("overflow")
    return v


def power(a, b):
    if b == 0:
        return 1
    if a in (0, 1):
        return a
    if a == -1:
        return 1 if b % 2 == 0 else -1
    r = 1
    for _ in range(b):
        r *= a
        if r < LO or r > HI:
            raise Err("overflow")
    return r


FUN = {"min": 2, "max": 2, "abs": 1}


def ev(e, env):
    k = e[0]
    if k == "int":
        return chk(e[1])
    if k == "var":
        if e[1] not in env:
            raise Err("unknown variable " + e[1])
        return env[e[1]]
    if k == "neg":
        return chk(-ev(e[1], env))
    if k == "call":
        name, args = e[1], e[2]
        if name not in FUN:
            raise Err("unknown function " + name)
        if len(args) != FUN[name]:
            raise Err("wrong number of arguments to " + name)
        vals = [ev(a, env) for a in args]
        if name == "min":
            return min(vals)
        if name == "max":
            return max(vals)
        return chk(abs(vals[0]))
    o = e[1]
    a = ev(e[2], env)
    b = ev(e[3], env)
    if o == "+":
        return chk(a + b)
    if o == "-":
        return chk(a - b)
    if o == "*":
        return chk(a * b)
    if o in "/%":
        if b == 0:
            raise Err("division by zero")
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        if o == "/":
            return chk(q)
        return a - b * q
    if b < 0:
        raise Err("negative exponent")
    return power(a, b)


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "program.txt"), encoding="utf-8", errors="replace") as f:
        lines = f.read().split("\n")
    env = {}
    out = []
    for n, line in enumerate(lines, 1):
        if not line.strip():
            continue
        try:
            toks = tokenize(line)
            if not toks:
                continue
            name = None
            if toks[0] == ("name", "let"):
                if len(toks) < 3 or toks[1][0] != "name" or toks[2] != ("op", "="):
                    raise Syn()
                name = toks[1][1]
                p = Parser(toks[3:])
            else:
                p = Parser(toks)
            tree = p.expr()
            if p.p != len(p.t):
                raise Syn()
            v = ev(tree, env)
            if name is not None:
                env[name] = v
                out.append("%d: %s = %d" % (n, name, v))
            else:
                out.append("%d: %d" % (n, v))
        except Syn:
            out.append("%d: error: syntax error" % n)
        except Err as e:
            out.append("%d: error: %s" % (n, e))
    print("\n".join(out))


