            toks.append(("name", s[i:j]))
            i = j
        elif c in "+-*/%^(),=":
            toks.append((c, c))
            i += 1
        else:
            raise Syn()
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.p = 0

    def peek(self):
        return self.t[self.p][0] if self.p < len(self.t) else None

    def take(self, k=None):
        if self.p >= len(self.t) or (k and self.t[self.p][0] != k):
            raise Syn()
        v = self.t[self.p]
        self.p += 1
        return v

    def expr(self):
        left = self.term()
        while self.peek() in ("+", "-"):
            op = self.take()[0]
            left = ("bin", op, left, self.term())
        return left

    def term(self):
        left = self.factor()
        while self.peek() in ("*", "/", "%"):
            op = self.take()[0]
            left = ("bin", op, left, self.factor())
        return left

    def factor(self):
        if self.peek() == "-":
            self.take()
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.peek() == "^":
            self.take()
            return ("bin", "^", a, self.factor())
        return a

    def atom(self):
        k = self.peek()
        if k == "int":
            return ("int", self.take()[1])
        if k == "name":
            name = self.take()[1]
            if self.peek() == "(":
                self.take()
                args = [self.expr()]
                while self.peek() == ",":
                    self.take()
                    args.append(self.expr())
                self.take(")")
                return ("call", name, args)
            return ("var", name)
        if k == "(":
            self.take()
            e = self.expr()
            self.take(")")
            return e
        raise Syn()


def chk(v):
    if v < MIN or v > MAX:
        raise Err("overflow")
    return v


def tdiv(a, b):
    q = abs(a) // abs(b)
    return q if (a < 0) == (b < 0) else -q


FUNCS = {"min": 2, "max": 2, "abs": 1}


def ev(node, env):
    k = node[0]
    if k == "int":
        return chk(node[1])
    if k == "var":
        if node[1] not in env:
            raise Err("unknown variable " + node[1])
        return env[node[1]]
    if k == "neg":
        return chk(-ev(node[1], env))
    if k == "call":
        name, args = node[1], node[2]
        if name not in FUNCS:
            raise Err("unknown function " + name)
        if len(args) != FUNCS[name]:
            raise Err("wrong number of arguments to " + name)
        vals = [ev(a, env) for a in args]
        if name == "min":
            return min(vals)
        if name == "max":
            return max(vals)
        return chk(abs(vals[0]))
    op = node[1]
    a = ev(node[2], env)
    b = ev(node[3], env)
    if op == "+":
        return chk(a + b)
    if op == "-":
        return chk(a - b)
    if op == "*":
        return chk(a * b)
    if op in "/%":
        if b == 0:
            raise Err("division by zero")
        q = tdiv(a, b)
        if op == "/":
            return chk(q)
        return a - b * q
    if b < 0:
        raise Err("negative exponent")
    if a in (0, 1):
        return 1 if b == 0 else a
    if a == -1:
        return 1 if b % 2 == 0 else -1
    if b > 64:
        raise Err("overflow")
    return chk(a ** b)


