        try:
            toks = tokenize(line)
            name = None
            p = Parser(toks)
            if toks and toks[0] == ("name", "let"):
                p.take()
                name = p.take("name")[1]
                p.take("=")
            tree = p.expr()
            if p.p != len(toks):
                raise Syn()
        except Syn:
            out.append("%d: error: syntax error" % n)
            continue
        try:
            v = ev(tree, env)
        except Err as e:
            out.append("%d: error: %s" % (n, e))
            continue
        if name is not None:
            env[name] = v
            out.append("%d: %s = %d" % (n, name, v))
        else:
            out.append("%d: %d" % (n, v))
    print("\n".join(out))


