    if op == "-":
        return chk(a - b)
    if op == "*":
        return chk(a * b)
    if op in "/%":
        if b == 0:
            raise Err("division by zero")
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        if op == "/":
            return chk(q)
        return chk(a - b * q)
    if b < 0:
        raise Err("negative exponent")
    if a in (0, 1):
        return 1 if b == 0 else a
    if a == -1:
        return 1 if b % 2 == 0 else -1
    if b > 64:
        raise Err("overflow")
    return chk(a ** b)


def main():
    d = os.environ.get("INPUT", "input")
    with open(os.path.join(d, "program.txt"), encoding="utf-8", errors="replace") as f:
        lines = f.read().split("\n")
    env = {}
    out = []
    for i, line in enumerate(lines, 1):
        if not line.strip():
            continue
        try:
            toks = tokenize(line)
            target = None
            if toks and toks[0] == ("name", "let"):
                if len(toks) < 3 or toks[1][0] != "name" or toks[2] != ("op", "="):
                    raise Err("syntax error")
                target = toks[1][1]
                p = Parser(toks[3:])
            else:
                p = Parser(toks)
            tree = p.expr()
            if p.p != len(p.t):
                raise Err("syntax error")
            v = ev(tree, env)
            if target is not None:
                env[target] = v
                out.append("%d: %s = %d" % (i, target, v))
            else:
                out.append("%d: %d" % (i, v))
        except Err as e:
            out.append("%d: error: %s" % (i, e))
    print("\n".join(out))


main()

import os, sys, json, hmac, hashlib, sqlite3, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, unquote

DB = os.environ["DB"]
SECRETS = os.environ["SECRETS"]
LOG = os.environ["LOG"]
PORT = int(os.environ["PORT"])

LOCK = threading.Lock()
TYPES = ("subscription.created", "subscription.activated", "payment.failed", "subscription.canceled")
TRANS = {
    "subscription.created": ({"none"}, "created"),
    "subscription.activated": ({"created", "past_due"}, "active"),
    "payment.failed": ({"active"}, "past_due"),
    "subscription.canceled": ({"created", "active", "past_due"}, "canceled"),
}


def connect():
    c = sqlite3.connect(DB, timeout=30, isolation_level=None)
    return c


def init():
    c = connect()
    c.execute("CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, sub TEXT, seq INTEGER, type TEXT, status TEXT)")
    c.execute("CREATE TABLE IF NOT EXISTS subs(id TEXT PRIMARY KEY, state TEXT, seq INTEGER, history TEXT)")
    c.execute("CREATE INDEX IF NOT EXISTS ev_sub ON events(sub, status, seq)")
    c.close()


def log(line):
    with open(LOG, "a", encoding="utf-8") as f:
        f.write(line + "\n")


def secret():
    with open(os.path.join(SECRETS, "webhook.key"), "rb") as f:
        d = f.read()
    if d.endswith(b"\n"):
        d = d[:-1]
    return d


def process(ev):
    c = connect()
    try:
        c.execute("BEGIN IMMEDIATE")
        if c.execute("SELECT 1 FROM events WHERE id=?", (ev["id"],)).fetchone():
            c.execute("COMMIT")
            return 200, {"status": "duplicate"}
        sid = ev["subscription"]
        row = c.execute("SELECT state, seq, history FROM subs WHERE id=?", (sid,)).fetchone()
        if row:
            state, last, hist = row[0], row[1], json.loads(row[2])
        else:
            state, last, hist = "none", 0, []
        seq = ev["seq"]
        if seq <= last:
            c.execute("INSERT INTO events VALUES(?,?,?,?,?)", (ev["id"], sid, seq, ev["type"], "stale"))
            c.execute("COMMIT")
            return 200, {"status": "stale"}
        if seq > last + 1:
            c.execute("INSERT INTO events VALUES(?,?,?,?,?)", (ev["id"], sid, seq, ev["type"], "queued"))
            c.execute("COMMIT")
            return 202, {"status": "queued"}
        c.execute("INSERT INTO events VALUES(?,?,?,?,?)", (ev["id"], sid, seq, ev["type"], "applied"))
        cur = ev
        applied = 0
        logs = []
        while True:
            frm, to = TRANS[cur["type"]]
            if state in frm:
                state = to
                hist.append(state)
            else:
                logs.append("invalid transition " + cur["id"])
            last = cur["seq"]
            applied += 1
            nxt = c.execute("SELECT id, type FROM events WHERE sub=? AND status='queued' AND seq=? LIMIT 1",
                            (sid, last + 1)).fetchone()
            if not nxt:
                break
            c.execute("UPDATE events SET status='applied' WHERE id=?", (nxt[0],))
            cur = {"id": nxt[0], "type": nxt[1], "seq": last + 1}
        c.execute("UPDATE events SET status='stale' WHERE sub=? AND status='queued' AND seq<=?", (sid, last))
        c.execute("INSERT OR REPLACE INTO subs VALUES(?,?,?,?)", (sid, state, last, json.dumps(hist)))
        c.execute("COMMIT")
        for l in logs:
            log(l)
        return 200, {"status": "applied", "applied": applied}
    except Exception:
        try:
            c.execute("ROLLBACK")
        except Exception:
            pass
        raise
    finally:
        c.close()


def valid(ev):
    return (isinstance(ev, dict)
            and isinstance(ev.get("id"), str)
            and isinstance(ev.get("type"), str) and ev["type"] in TYPES
            and isinstance(ev.get("subscription"), str)
            and isinstance(ev.get("seq"), int) and not isinstance(ev["seq"], bool)
            and ev["seq"] >= 1)


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj):
        b = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(b)))
        self.end_headers()
        self.wfile.write(b)

    def do_POST(self):
        n = int(self.headers.get("content-length") or 0)
        body = self.rfile.read(n) if n > 0 else b""
        path = urlsplit(self.path).path
        if path != "/webhooks":
            return self.send(404, {"error": "not found"})
        sig = self.headers.get("x-signature")
        exp = "sha256=" + hashlib.sha256(secret() + b"." + body).hexdigest()
        if sig is None or not hmac.compare_digest(sig.encode("utf-8", "replace"), exp.encode()):
            log("rejected signature")
            return self.send(401, {"error": "bad signature"})
        try:
            ev = json.loads(body.decode("utf-8"))
        except Exception:
            ev = None
        if not valid(ev):
            return self.send(400, {"error": "invalid event"})
        with LOCK:
            code, obj = process(ev)
        self.send(code, obj)

    def do_GET(self):
        path = urlsplit(self.path).path
        if path.startswith("/subscriptions/") and len(path) > len("/subscriptions/"):
            sid = unquote(path[len("/subscriptions/"):])
            with LOCK:
                c = connect()
                try:
                    row = c.execute("SELECT state, seq, history FROM subs WHERE id=?", (sid,)).fetchone()
                finally:
                    c.close()
            if row:
                return self.send(200, {"id": sid, "state": row[0], "seq": row[1], "history": json.loads(row[2])})
        self.send(404, {"error": "not found"})

    def do_PUT(self):
        self.drain()

    do_DELETE = do_PATCH = do_PUT

    def drain(self):
        n = int(self.headers.get("content-length") or 0)
        if n > 0:
            self.rfile.read(n)
        self.send(404, {"error": "not found"})


init()
ThreadingHTTPServer(("127.0.0.1", PORT), H).serve_forever()
